(5517169, 796188, 57460, '<td valign="top">This appears it was intended for the Friends challenge, unless she also goes by the name of Stewie :)</td>', 'This appears it was intended for the Friends challenge, unless she also goes by the name of Stewie :)', '2009-06-06 17:26:50.000000', NULL, 1),
